      out_idx_o [j*IDX_W  +: IDX_W]  = mo_x[j];
    end
  end

  stream_xbar #(
    .NumInp      (N_IN),
    .NumOut      (N_OUT),
    .DataWidth   (DATA_W),
    .OutSpillReg (1'b0),
    .ExtPrio     (1'b0),      // internal round robin
    .AxiVldRdy   (1'b1),      // strict valid/ready handshaking
    .LockIn      (1'b1)       // an arbitration decision is held until it completes
  ) i_xbar (   // MUTANT xb_m8_duplicate_on_stall_release -- violates R4: the beat released after a stall of four or more cycles is delivered twice
    .clk_i, .rst_ni,
    .flush_i (1'b0),
    .rr_i    ('0),
    .data_i  (d_i),
    .sel_i   (s_i),
