    .ExtPrio     (1'b0),      // internal round robin
    .AxiVldRdy   (1'b1),      // strict valid/ready handshaking
    .LockIn      (1'b1)       // an arbitration decision is held until it completes
  ) i_xbar (   // MUTANT xb_m10_ready_glitch_when_all_stalled -- violates I2: input 0 is accepted for one cycle although nothing can take its beat, when every output is stalled
